-- Rifts World Book 8: Japan - its bestiary and its notable NPCs.
-- 8 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-japan-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 8 creatures are in' AS assertion, count(*) AS got, 8 AS want
  FROM creatures WHERE slug IN ('japan-oni-master', 'japan-oni-mystic', 'japan-goblin-spider', 'japan-imp', 'japan-hannya-demon', 'japan-shikome-kido-mi-dragon', 'japan-kumo-mi-cloud-dragon', 'japan-asama-tatsu-volcano-dragon');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('japan-oni-master', 'japan-oni-mystic', 'japan-goblin-spider', 'japan-imp', 'japan-hannya-demon', 'japan-shikome-kido-mi-dragon', 'japan-kumo-mi-cloud-dragon', 'japan-asama-tatsu-volcano-dragon');
SELECT 'the creatures carry 42 attacks' AS assertion, count(*) AS got, 42 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('japan-oni-master', 'japan-oni-mystic', 'japan-goblin-spider', 'japan-imp', 'japan-hannya-demon', 'japan-shikome-kido-mi-dragon', 'japan-kumo-mi-cloud-dragon', 'japan-asama-tatsu-volcano-dragon');

