INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('japan-oni-master', 'Oni Master', 'demon', 'rifts', 0, 'Evil or anarchist', '{"IQ":"2D6+6","ME":"2D6+8","MA":"2D6","PS":"28+2D6","PP":"14+2D6","PE":"18+2D6","PB":"1D6"}', NULL, NULL, '3D6x10+100', 'PEx4', NULL, 'Spd is not a fixed formula: it comes from the oni Legs table (3D6 up to 6D6+10 by leg type). M.D.C. gets the Other Features table bonuses (scales +35, lumpy flesh +10, hairy body +20, boils +25, pot belly +10, hunchback +5, fur +10). Horror Factor is 13 plus the Head Shape table bonus (0 to +4). P.P.E. is P.E. x4 plus 10 per level of experience. Bio-regeneration is 1D4x10 M.D. per hour. All attributes are supernatural. Bite and arm damage come from the oni Mouth and Arms and Hands tables rather than this block.', NULL, 13, '{"initiative":2,"strike":1,"parry":1,"dodge":1,"pull":2,"roll":1}', 'Plus physical attribute and martial arts bonuses: +1 to save vs mind control, +8 to save vs horror factor, and one extra attack per melee round. Combat training is karate or jujitsu. The block states no base number of attacks per melee.', 'Very limited: intelligence +4%, track humanoids +10%, land navigation +15%, climb +10%, swim +10%, two rogue or espionage skills of choice, W.P. spear, W.P. sword and three of choice (any); speaks Japanese, Gobblely and Faerie at 98% and can learn two other languages at +10%. Six secondary skills from espionage, physical, technical, rogue and wilderness. Average NPC master warrior is level 1D4+1, elite warriors 1D4+3, oni master clan leaders 1D4+6.', 'Sees 500 ft in total darkness, takes half damage from fire and cold, cannot be possessed or sicken, and heals 1D4x10 M.D. an hour.', 'Natural powers, not learned spells; up to 8 per 24 hours, from one of two sets. 01-50: concealment, detect concealment, chameleon, mask of deceit, repel animals, blind, sickness, mute, spoil (food & water), fear, trance, calling, domination, compulsion, cure illness, agony, life drain, luck curse, minor curse, constrain being, banishment, tongues. 51-00: breathe without air, float in air, thunderclap, fly as the eagle, escape, sleep, time slip, teleport: lesser, energy disruption, impervious to energy, energy bolt, call lightning, fire ball, wind rush, summon fog, summon & control rain, summon storm, tongues.', 'None', '5 to 6 feet tall (1.5 to 1.8 m)', '160 to 250 pounds (72 to 112.5 kg)', '300+ years', 'Same range as the lesser oni: Japan, Taiwan, Korea, China and parts of India and Southeast Asia, mostly wilderness, mountains, slums, sewers and ruins; in Japan mainly the Zone and the Freelands.', 'Powerful oni and demons, vampires, evil dragons, priests and sorcerers may be treated as allies or even leaders; weaker beings are minions and slaves. A few serve in Horune pirate and mercenary teams.', 'As the lesser oni but with deeper hatred: demon quellers, bishamon, samurai, Atlantean Undead Slayers and strong summoners and mages.', 'Strictly an NPC villain; no player option. Roughly one oni in ten is a master. Roll the body with the same oni creation tables as the lesser oni.', 'A bigger, bolder and tougher cousin of the ordinary oni. Masters relish challenges, hate human warriors and demon hunters, and usually meet trouble head on instead of scheming. Their secret ritual lets oni enchant weapons and armor to mega-damage.', 'Rifts World Book 8: Japan p.203-204'),
('japan-oni-mystic', 'Oni Mystic', 'demon', 'rifts', 0, 'Typically miscreant or diabolic, but can be any alignment', '{"IQ":"10+2D6","ME":"16+2D6","MA":"3D6","PS":"28+2D6","PP":"12+2D6","PE":"12+3D6","PB":"2D4"}', NULL, NULL, '1D4x100+200', 'PEx6', '3D4x10', 'Spd is not a fixed formula: it comes from the oni Legs table (3D6 up to 6D6+10 by leg type). M.D.C. gets the Other Features table bonuses as for any oni. Horror Factor is 14 plus the Head Shape table bonus (0 to +4). P.P.E. is P.E. x6 plus 12 per level of experience; I.S.P. is 3D4x10 plus 10 per level. Bio-regeneration is 1D4x10 M.D. per hour. All attributes are supernatural. Roll the same body tables as other oni, except the eyes: a mystic has three.', NULL, 14, '{"initiative":2,"strike":1,"parry":1,"dodge":1,"pull":2,"roll":1}', 'Plus physical attribute and martial arts bonuses: +1 to save vs mind control, +8 to save vs horror factor, and one extra attack per melee round. Combat training is karate, kendo or jujitsu. The block states no base number of attacks per melee.', 'Detect ambush +15%, detect concealment +10%, calligraphy +10%, forgery +10%, go +10%, intelligence +14%, imitate voice +8%, track humanoids +15%, land navigation +15%, wilderness survival +15%, first aid +5%, camouflage +5%, prowl +15%, climb +10%, swim +10%, W.P. sword, W.P. modern weapon of choice and two of choice (any); speaks Japanese, Gobblely and Faerie at 98% and can learn two other languages at +10%. Three secondary skills from espionage, physical, technical, rogue and wilderness. Mystic martial arts powers: one art of invisibility at levels 1 and 4, one body hardening exercise at level 8, one zenjoriki power at level 12. Average NPC mystic is level 1D4+1, mid-level 1D4+3, war chief or clan leader 1D4+6.', 'Sees 500 ft in the dark, sees the invisible, can vanish at will, takes half damage from fire and cold, resists possession and disease, and heals 1D4x10 M.D. an hour.', 'Armor of Ithan, mystic alarm, apparition, multiple image, mask of deceit, chameleon, fool''s gold, escape, fly like the eagle, befuddle, energy bolt, fireball, call lightning, negate magic, metamorphosis: insect, mystic portal, commune with spirits and tongues, plus one additional spell of choice per level of experience, from spell levels 1-10.', 'Powers of the third eye: detect psionics, clairvoyance, mind block, presence sense, see aura, sense magic, telepathy, resist fatigue, resist hunger, bio-manipulation, mind bolt and psi-sword.', '6 to 8 feet tall (1.8 to 2.4 m)', '200 to 400 pounds (90 to 180 kg)', '300+ years', 'Same range as the lesser oni. A mystic often travels alone with about 2D4 minions (an imp or two, an oni master and some lesser oni), or rules a village or city.', 'Allies with any evil creature, above all dragons and dark gods, plus evil sorcerers and tyrants. It distrusts goblin spiders yet hires them as spies and assassins.', 'As the lesser oni but with deeper hatred: demon quellers, bishamon, samurai, Atlantean Undead Slayers and strong summoners and mages.', 'Strictly an NPC villain by the oni rules set out for lesser oni. About one oni in fifty is born a mystic, marked by its third eye.', 'The most gifted of the oni: a demon sorcerer and martial artist who commands clans and sometimes armies, rules towns and enslaves humans and D-bees. Clever, ambitious and familiar with basic human technology such as radios, rail guns and motorbikes, it makes a natural tyrant or assassin for hire.', 'Rifts World Book 8: Japan p.204-205'),
('japan-goblin-spider', 'Goblin Spider', 'demon', 'rifts', 0, 'Diabolic or miscreant', '{"IQ":"3D6+4","ME":"3D6+4","MA":"3D6+6","PS":"3D6+6","PP":"2D6+12","PE":"3D6+6","PB":"1D6","Spd":"4D6x3"}', NULL, NULL, '2D4x100', '1D4x100', '2D4x10', 'Spd 4D6x3 is for running or climbing. P.B. gets +4 in humanoid guise. P.P.E. gets 2D6 more per level of experience; I.S.P. gets 7 more per level (a major psionic). Horror Factor is 16 as a spider and 11 as an oni or imp. Regenerates 1D4x10 M.D.C. every five minutes and regrows limbs in 48 hours. All attributes are supernatural.', NULL, 16, '{"initiative":2,"strike":2,"parry":2,"dodge":3,"pull":6,"roll":2}', 'Plus physical attribute bonuses: parry is +4 as a giant spider, +10 to save vs horror factor, +2 to save vs magic, +5 to save vs possession. Four physical or psionic attacks per melee, or two by magic. Fire does double damage to it. The venom and blood do 3D6 M.D. with -2 on all combat rolls and halved speed and attacks for 2D6 minutes.', 'Radio: basic +5%, intelligence +16%, disguise +20% (via shape change, cannot look fully human), imitate voices/impersonate +10%, track humanoids +15%, camouflage +15%, demolitions +5%, acrobatics, streetwise +10%, poetry +10%; literacy and speaks Dragonese/Elf and ancient Greek (Atlantean) at 98%, literacy and speaks Japanese and Chinese at +20%; W.P. sword and two W.P. of choice. No martial arts; six secondary skills from any category. NPC level 1D4 if very young (under 800 years), 1D4+3 on average, 1D6+5 if experienced. It has no native language because spiders talk by telepathy and empathy.', 'Sees 1000 ft in the dark and the invisible, climbs surfaces at 98%, prowls at 60%, shrugs off poison, drugs and disease, tracks by blood scent 68% (-38% to pick out one person) over trails 48 hours cold. Limited shape-change (about a minute) into goblin, hob-goblin, imp or classic-oni shapes. Spins strong light webbing (10 minutes for a full web; a strand rated at 2400 lbs).', 'Most are ley line walkers (dimensional magic) or temporal wizards. All know dimensional portal, close Rift, mystic portal, shadow meld, eyes of Thoth, tongues and time slip, plus 10 other spells of choice from any level of spell magic or temporal wizardry.', 'Object read, telepathy, death trance, empathy, empathic transmission, bio-manipulation and mind block.', 'Spider form: about 9 ft (2.7 m) tall, 12 ft (3.65 m) long, goblin head about 4 ft (1.2 m) up; humanoid form 3 to 5 ft (0.9 to 1.5 m)', '1200 pounds in spider form (540 kg)', '3000+ years, some reach 5000', 'Anywhere, but commonest in Asia; at least 10,000 live in Japan and about a hundred times that in China. A dozen have slipped into Atlantis.', 'Loners who keep to their own kind, though they sometimes work with oni mystics, evil dragons, evil sorcerers and dark gods.', 'Every mortal is a plaything, with humanity the current favorite target. They dislike the Splugorth and their minions, and the feeling is returned.', 'Strictly an NPC villain; no player option.', 'A giant furry eight-legged spider wearing a distorted goblin face, exiled from its homeworld for mass slaughter. It delights in torture and assassination, mimics goblins, imps and oni, and has studied True Atlanteans for centuries. Some pose as tech-ninja or run crime rings.', 'Rifts World Book 8: Japan p.207-209'),
('japan-imp', 'Japanese Imp', 'demon', 'rifts', 0, 'Evil or anarchist', '{"IQ":"2D6+4","ME":"2D6+4","MA":"2D6+4","PS":"2D6+6","PP":"2D6+8","PE":"2D6+8","PB":"1D6","Spd":"2D6+12"}', NULL, NULL, '2D4x10+20', 'PEx2', NULL, 'P.P.E. is P.E. x2 plus 1D6 per level of experience. Bio-regenerates 2D6 M.D. every 10 minutes. Three attacks per melee, plus one at levels 5 and 11; no formal hand to hand training. All attributes are supernatural. The dodge bonus prints as ''44 to dodge'' in both the text layer and the page ink; read here as +4.', NULL, 9, '{"initiative":2,"strike":2,"parry":1,"dodge":4,"pull":1,"roll":2}', 'Plus physical attribute bonuses, and +6 to save vs horror factor. Silver weapons do their S.D.C. damage as mega-damage to an imp, and most imps cannot swim and drown easily.', 'Intelligence +4%, track humanoids +20%, land navigation +15%, climb +10%, palming +10%, pick locks +10%, pick pockets +5%, prowl +10%, imitate voices +6%, W.P. knife and one of choice; speaks Japanese, Gobblely and Faerie at 98% and can learn two other languages at +10%. Four secondary skills from espionage, physical, technical, rogue, wilderness and W.P. Average imp is level 3, elite and experienced imps 1D4+3, ancient imps 1D4+5.', 'Sees 500 ft in the dark, takes half damage from fire and cold, resists disease, and regenerates 2D6 M.D. every 10 minutes.', 'Mystic martial arts powers: any three arts of invisibility.', 'None', '3 feet tall (0.9 m)', '50 pounds (22.6 kg)', '8000+ years', 'Same range as the oni: Japan, Taiwan, Korea, China and parts of India and Southeast Asia, in wilderness, mountains, slums, sewers and ruins; in Japan mainly the Zone and the Freelands.', 'Evil and powerful beings in need of a lackey.', 'Basically the same as the oni.', 'An NPC villain; the tag line lists no player option.', 'A miniature oni with big yellow eyes, small fangs, a messy crimson or dark green mane and red or tan skin. Smarter than most oni and fond of cruel pranks, it works as thief, spy, kidnapper or sly servant to whichever strong master offers it thrills.', 'Rifts World Book 8: Japan p.209-210'),
('japan-hannya-demon', 'Hannya Demon', 'demon', 'rifts', 0, 'Diabolic', '{"IQ":"8","ME":"2D6+6","MA":"1D6","PS":"2D6+13","PP":"2D6+6","PE":"2D6+10","PB":"1D4","Spd":"2D6+13"}', NULL, NULL, '1D6x10+100', '1D6x10+60', NULL, 'Spd 2D6+13 is running; flying is 66 (45 mph / 72 km). In human guise M.A. is 1D6+13 and P.B. is 20+1D4. Bio-regenerates 1D4x10 M.D. per hour, and another 2D6x10 M.D.C. by the end of every night. Horror Factor 14 in true form, zero in human guise. Three attacks per melee round, or one by magic. All attributes are supernatural. Female only.', NULL, 14, '{"strike":2,"parry":2,"dodge":4,"pull":2,"roll":1}', 'Plus physical attribute bonuses: +3 to save vs psionic attack, +3 to save vs magic, +5 to save vs horror factor. Fire does full damage, silver does mega-damage equal to its S.D.C. damage, and magic weapons (samurai swords included) do their normal M.D. It must show its true form before it can attack.', 'Very limited: track humanoids +10%, land navigation +15%, cook, dance, sing, speak Japanese and Gobblely at 98%. No secondary skills. No experience level; counts as 6th level for skills and magic.', 'Sees 500 ft in the dark and the invisible, flies, vanishes at will, and is immune to cold, poison, drugs, magic poisons, disease and possession. A severed limb must be rejoined overnight to heal; one destroyed by fire is lost for good. It can shape change into a beautiful woman.', 'Natural abilities only (no spell learning), all as a 6th level wizard: mask of deceit, repel animals, float in air, thunderclap, escape and tongues.', 'None', '5 to 6 feet tall (1.5 to 1.8 m)', '160 pounds (112.5 kg)', '10,000+ years', 'Same range as the oni. She lurks at crossroads and bridges in the guise of a lovely maiden or grieving widow, and also preys in alleys on the homeless.', 'None as such; she sometimes keeps company with oni and other dark creatures.', 'As the oni, though she cares more about hunting and feeding than wealth or power.', 'Strictly an NPC villain, female only; no player option.', 'A hideous demonic hag with bulging eyes, crooked yellow teeth and clawed hands and feet. A cowardly illusionist and shape-changer, she lures young warriors, priests and monks with a false beauty, then feeds on blood, entrails and P.P.E. A savage but unskilled fighter.', 'Rifts World Book 8: Japan p.210-211'),
('japan-shikome-kido-mi-dragon', 'Shikome Kido-Mi Dragon', 'dragon', 'rifts', 0, 'Typically miscreant or diabolic, occasionally anarchist or miscreant', '{"IQ":"3D6+10","ME":"3D6+10","MA":"3D6+6","PS":"2D6+32","PP":"3D6+10","PE":"3D6+10","PB":"3D6+10","Spd":"6D6"}', NULL, NULL, '2D4x1000+200', '2D4x100+300', '3D6x10', 'Adult figures stored. M.D.C. is 2D4x1000+200 for a mature adult; 1D4x100+50 for a hatchling and 1D4x1000+800 for a young adult. P.P.E. is 2D4x100+300 for a mature adult (the magic line prints 2D4x100); 1D4x100 for a hatchling and 1D6x100+150 for a young adult. Spd is running and climbing. Eight physical attacks per melee (four for a hatchling, six for a young adult) or two by magic. Regenerates 1D4x10 M.D.C. per minute. All attributes are supernatural.', NULL, 16, '{"initiative":3,"strike":1,"parry":1,"dodge":2,"roll":2}', 'Plus physical attribute bonuses: +8 to save vs horror factor and +2 on all saving throws. Silver weapons do mega-damage, fire does normal damage, and magic weapons (the living samurai sword, rune weapons, Millennium Tree weapons) do double damage. Prefers magic and magic weapons to melee.', 'Mostly studies magic; likely knows palming +10%, streetwise +12%, detect concealment +10%, intelligence +10%, camouflage +15%, calligraphy +10%, forgery +10%, bonsai +20%, Go +10%, Japanese mythology +20%, demon & monster lore +20%, W.P. sword, W.P. blunt and one W.P. of choice; speaks Japanese, Dragonese/Elf and Gobblely at 98% and can learn two other languages at +10%. NPC level 1D4+3 for hatchlings and young adults, 2D4+5 for mature adults.', 'Sees 1200 ft in the dark and the invisible, climbs 98%, prowls 60%, tracks by blood scent 78%, knows a creature by scent 68% (-30% for one specific person), resizes from 12 to 42 feet, turns invisible, teleports between dimensions 88%, and resists cold, poison, disease and possession.', '70% know all spell magic of levels 1-8, all dimensional magic, sanctum, talisman, amulet, create zombie and create mummy. 29% know all temporal raider magic (Rifts England), all spell magic of levels 1-3 and all dimensional magic. 1% know all spells of levels 1-5 and the secrets of tattoo magic. 40% can also make elemental shurikens, 10,000 strength nunchaku and magic powders for the Holy Incense Burner. Knows all the mystic martial arts powers (invisibility, body hardening, zenjoriki) but cannot use them; it teaches them to servants, rarely more than three to one person.', 'Clairvoyance, see aura, sense magic, sixth sense, telepathy, death trance, automatic mind block defense and hypnotic suggestion.', '12 feet (3.6 m) to 42 feet (12.8 m) snout to tail tip; stands on hind legs when angry', 'One to three tons', '8000 years', 'Native to another dimension; found worldwide but favors Japan, Korea, China, India and Indonesia. Keeps mountain retreats and may rule villages or cities from a castle.', 'Has minions, servants and slaves rather than friends (oni, wizards, ninja and others); at most an accomplice.', 'Regards everyone, other shikome kido-mi and gods included, as a rival. Demon quellers list it among their targets.', 'Ideal for NPCs and villains. If a player character is allowed, use the hatchling R.C.C. rules from the Rifts RPG, starting at level one.', 'The Hideous Sorcerer Serpent, a scheming dragon that dangles arcane secrets before mortals to corrupt and control them. Proud and greedy, it works with others only for its own ends. Legend credits it as the source of the ninja arts of invisibility.', 'Rifts World Book 8: Japan p.211-212'),
('japan-kumo-mi-cloud-dragon', 'Kumo-Mi, Cloud Dragon', 'dragon', 'rifts', 0, 'Any; can be good, anarchist or evil', '{"IQ":"3D6+10","ME":"3D6+10","MA":"2D6+15","PS":"2D6+28","PP":"3D6+8","PE":"3D6+12","PB":"3D6+10","Spd":"3D6+88"}', NULL, NULL, '2D4x1000+100', '1D6x100+200', '3D4x10', 'Adult figures stored. M.D.C. is 2D4x1000+100 for a mature adult; 1D4x100+50 for a hatchling and 1D4x1000+600 for a young adult. P.P.E. is 1D6x100+200 for a mature adult; 1D4x100 for a hatchling and 1D6x100+80 for a young adult. Spd is flying or snaking through the sky (over 55 mph / 88 km). Seven physical or psionic attacks per melee (four for a hatchling, six for a young adult) or two by magic. Regenerates 1D4x10 M.D.C. per minute. Horror Factor is printed as awe. All attributes are supernatural.', NULL, 15, '{"initiative":3,"strike":1,"parry":1,"dodge":4,"roll":3}', 'Plus physical attribute bonuses: +7 to save vs horror factor and +2 on all saving throws. Silver weapons do mega-damage; fire and magic weapons do normal damage; earth elementals do double damage. Prefers magic and magic weapons to melee. Mystic martial arts knowledge: one art of invisibility and one zenjoriki power.', 'Scholarly only: all technical skills (lores, languages, literacy) except computers and photography at +10%; basic math +10%, calligraphy, land navigation, identify plants and fruits, gardening, dance, sing, play wind instruments. NPC level 1D4+2 for hatchlings and young adults, 2D4+4 for mature adults.', 'Sees 1200 ft in the dark and the invisible, vanishes at will, climbs 98%, prowls 60%, resizes from 15 to 60 feet, teleports between dimensions 88%, and resists cold, poison, disease and possession.', '50% know all air, illusion and dimensional magic spells from the Rifts RPG plus tongues, magic pigeon, Eyes of Thoth, sanctum, dispel magic, negate magic, anti-magic cloud and both protection circles. 50% know all air warlock spells from Rifts Conversion Book One.', 'All healing abilities plus telepathy, empathy and mind block.', '15 feet (4.6 m) to 60 feet (18.3 m) snout to tail tip', 'Four tons', '8000+ years', 'Native to another dimension; found worldwide but favors Japan, Korea, China, India and Indonesia. Lives high in cloud-wreathed mountains. Fewer than 100 exist in the Japanese islands.', 'Varies with temperament: some are kind to humans, some aloof, some cruel. Usually drawn to trustworthy thinkers and mages, and tends to avoid other dragons.', 'Often clashes with elementals and power-hungry magical or supernatural beings.', 'Ideal for NPCs and villains. If a player character is allowed, use the hatchling R.C.C. rules from the Rifts RPG, starting at level one.', 'The cloud serpent: a long, scaled, eel-like dragon in white-green or pale blue with diamond eyes and a pair of horns, drifting through the air near mountaintops. Moral outlook varies; one guards Mount Fuji while another is a despot over an oni kingdom.', 'Rifts World Book 8: Japan p.213-214'),
('japan-asama-tatsu-volcano-dragon', 'Asama-Tatsu, Volcano Dragon', 'dragon', 'rifts', 0, 'Any; good, anarchist or evil', '{"IQ":"2D6+16","ME":"2D6+10","MA":"2D6+10","PS":"2D6+36","PP":"2D6+10","PE":"2D6+16","PB":"3D6+10","Spd":"3D6+88"}', NULL, NULL, '2D4x1000+1400', '2D4x100+200', '3D4x10', 'Adult figures stored. M.D.C. is 2D4x1000+1400 for a mature adult; 1D4x100+50 for a hatchling and 1D6x1000+600 for a young adult. P.P.E. is 2D4x100+200 for a mature adult; 1D4x100 for a hatchling and 1D6x100+100 for a young adult. Spd is flying or snaking through the sky (over 55 mph / 88 km). Seven physical or psionic attacks per melee (four for a hatchling, six for a young adult) or two by magic. Regenerates 1D4x10 M.D.C. per minute. Horror Factor is printed as awe. All attributes are supernatural. The size line says it can shrink to 15 feet while the natural abilities say 20.', NULL, 16, '{"initiative":4,"strike":2,"parry":2,"dodge":2,"roll":2}', 'Plus physical attribute bonuses: +8 to save vs horror factor and +2 on all saving throws. Cold attacks and cold magic do double damage; magic weapons and mega-damage weapons do normal damage. Prefers magic but fights fiercely when cornered. Mystic martial arts knowledge: one zenjoriki power at levels 2, 7, 12 and 20.', 'Scholarly only: all science and technical skills, including computers, plus all pilot skills and medical and herbal skills, all at +20%. NPC level 1D4+2 for hatchlings and young adults, 2D4+5 for mature adults.', 'Sees 1200 ft in the dark and the invisible, cannot be hurt by fire or heat of any kind, plasma and magical flame included, and is immune to poisons, disease and possession, climbs 90%, swims 90%, resizes from 20 to 100 feet, teleports between dimensions 92% and teleports itself 96%.', '50% are ley line walkers who know all spells of levels 1-7 plus 12 more from levels 8-15. 20% are diabolists (Rifts Conversion Book One). 20% are techno-wizards who know all spells of levels 1-5 plus six of choice from higher levels. 10% are NPC alchemists who can make every item in the magic section except rune weapons.', 'All physical abilities plus telepathy, pyrokinesis, mind block auto-defense and P.P.E. shield.', '15 feet (4.6 m) to 100 feet (30.5 m) snout to tail tip; about 20 feet (6 m) tall at full size', 'Twenty two tons', '8000+ years', 'Native to another dimension; found worldwide but favors Japan, Korea, China, India and Indonesia. Said to live inside volcanoes, sometimes ruling a village or city from a castle.', 'Varies with temperament: some are kind to humans, some aloof, some cruel. Mostly loners who avoid other dragons; a few join monasteries as teachers.', 'Often clashes with power-hungry magical and supernatural beings.', 'Ideal for NPCs and villains. If a player character is allowed, use the hatchling R.C.C. rules from the Rifts RPG, starting at level one.', 'The volcano dragon: a huge golden-scaled, silver-eyed dragon with a unicorn horn and a golden-red mane, fireproof and quick to explode in anger. Reclusive scholar of great knowledge; most are aloof, and some teach in monasteries.', 'Rifts World Book 8: Japan p.214-215');
